{"sql": "WITH qualifying_patients AS (
  SELECT DISTINCT patient.id, patient.birthday
  FROM patient
  JOIN laboratory ON patient.id = laboratory.id
  WHERE patient.sex = 'M' AND laboratory."T-CHO" >= 250
)
SELECT AVG(
  EXTRACT(YEAR FROM NOW()) - EXTRACT(YEAR FROM qualifying_patients.birthday)
)
FROM qualifying_patients"}

